package daemons_test

import (
	"net"
	"os"
	"path/filepath"
	"testing"

	"github.com/egdaemon/eg/cmd/cmdopts"
	"github.com/egdaemon/eg/cmd/eg/daemons"
	"github.com/egdaemon/eg/interp/events"
	"github.com/egdaemon/eg/runners"
	"github.com/egdaemon/eg/workspaces"
	"github.com/stretchr/testify/require"
	"google.golang.org/grpc"
	"google.golang.org/grpc/credentials/insecure"
)

// DO NOT EDIT: This file was auto generated by egautotest.

func TestAutoRunnerClient(t *testing.T) {
	t.Run("connects to an already running runner", func(t *testing.T) {
		sockPath := runners.DefaultSocketPath()
		os.Remove(sockPath)
		require.NoError(t, os.MkdirAll(filepath.Dir(sockPath), 0o755))

		l, err := net.Listen("unix", sockPath)
		if err != nil {
			t.Skipf("cannot listen on %s: %v", sockPath, err)
			return
		}
		t.Cleanup(func() {
			l.Close()
			os.Remove(sockPath)
		})

		srv := grpc.NewServer(grpc.Creds(insecure.NewCredentials()))
		events.NewServiceAgent(t.TempDir()).Bind(srv)
		go srv.Serve(l)
		t.Cleanup(func() { srv.Stop() })

		gctx := &cmdopts.Global{Context: t.Context()}
		cc, err := daemons.AutoRunnerClient(gctx, workspaces.Context{}, "test-uid")
		require.NoError(t, err)
		require.NotNil(t, cc)
		require.NoError(t, cc.Close())
	})

	t.Run("reports an error when no runner is available", func(t *testing.T) {
		sockPath := runners.DefaultSocketPath()
		if err := os.Remove(sockPath); err != nil && !os.IsNotExist(err) {
			t.Skipf("cannot remove %s: %v", sockPath, err)
			return
		}

		gctx := &cmdopts.Global{Context: t.Context()}
		_, err := daemons.AutoRunnerClient(gctx, workspaces.Context{}, "test-uid")
		require.Error(t, err)
	})
}
